function taskTxt(key){
  const l = localStorage.getItem('aiapp_lang') || 'ar';
  return (TASK_I18N[l] || TASK_I18N.ar)[key];
}
function formatTaskPlan(steps, done){
  return taskTxt('title') + ':\n' + steps.map((s, i) => ((done && done[i]) ? '✅ ' : '⬜ ') + s).join('\n');
}
