function stripPplxCitations(s){
  return String(s || '')
    .replace(/\[\d{1,3}\]/g, '')
    // v285: حذف أي صورة يحشرها Perplexity داخل الرد (ماركداون أو رابط صورة مباشر)
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
    .replace(/https?:\/\/\S+\.(?:png|jpe?g|gif|webp)(?:\?\S*)?/gi, '');
}
