      while(__turns.length && __turns[0].role !== 'user') __turns.shift();
      const __size = () => __turns.reduce((n, m) => n + m.content.length, 0);
      while(__turns.length > 2 && __size() > MAX_CHARS) __turns.splice(0, 2); // زوجًا للحفاظ على التناوب
