    مطبخ: '#F5DDEE', كراج: '#E6E6E6', خدامة: '#EDE7DA', مسبح: '#BFE4F2',
    مكتب: '#E4EEDC', مخزن: '#EAEAEA', سلم: '#E0DCE8', ممر: '#F4F1EA',
