    maxSilenceMs: 26000,   // أقصى صمت مسموح — بعده يصف حتى لو لم يتغيّر المشهد
    diffThreshold: 0.10,   // نسبة البكسل المتغيّر التي تعني «مشهد جديد»
    maxDim: 1024,          // أقصى بُعد للإطار المرسل
